\begin{prop} 
(Example 3.7 of \cite{bocker1998})
If $T$ is a binary tree such that the interior edges of $T$ are labeled $E=\{e_1,...,e_{n-3}\}$, and $Q$ is a system of quartet trees such that each $q_i \in Q$ distinguishes a unique edge $e_i$ in $T$ with \[|supp(q_i)\backslash \bigcup_{j<i} supp(q_j)|= 1\] for $i=2,...,n-3$, then $Q$ is definitive. 
\label{bocker2}
\end{prop}

\begin{proposition}[ZFC] \label{propfgpstrength}
  The statement $\cf(\mathfrak{fgp})=\omega$ has some consistency strength.
\end{proposition}

\begin{prop}
Let $n\geq 3$ and let $\EKR$ be a maximal coclique of $\Gamma_{2n}$ such that the number of red spaces in $\EKR$ is $\OO(q^{n^2-2})$. Then $|\EKR|$ is $\OO(q^{n^2+n-2})$.
\end{prop}
